import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/api/api_client.dart';import '../../core/api/models.dart';import '../onboarding/onboarding_models.dart';import '../today/today_screen.dart';
final transactionsProvider=FutureProvider<List<TransactionDto>>((r)=>r.watch(apiClientProvider).transactions());
class TransactionsScreen extends ConsumerWidget{const TransactionsScreen({super.key});Future<void> add(BuildContext context,WidgetRef ref)async{final amount=TextEditingController(),category=TextEditingController(),description=TextEditingController();String? error;bool busy=false;final key='transaction-${DateTime.now().microsecondsSinceEpoch}';await showDialog<void>(context:context,builder:(dialog)=>StatefulBuilder(builder:(context,setLocal)=>AlertDialog(title:const Text('Добавить расход'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Сумма')),const SizedBox(height:8),TextField(controller:category,decoration:const InputDecoration(labelText:'Категория')),const SizedBox(height:8),TextField(controller:description,decoration:const InputDecoration(labelText:'Описание')),if(error!=null)Text(error??'',style:TextStyle(color:Theme.of(context).colorScheme.error))]),actions:[TextButton(onPressed:busy?null:()=>Navigator.pop(context),child:const Text('Отмена')),FilledButton(onPressed:busy?null:()async{final parsed=parseMoney(amount.text);if(parsed==null||category.text.trim().isEmpty){setLocal(()=>error='Введите положительную сумму и категорию');return;}setLocal(()=>busy=true);try{await ref.read(apiClientProvider).createExpense(amount:parsed,category:category.text.trim(),description:description.text.trim(),idempotencyKey:key);ref.invalidate(transactionsProvider);if(context.mounted)Navigator.pop(context);}catch(e){setLocal((){busy=false;error='$e';});}},child:const Text('Добавить'))])));amount.dispose();category.dispose();description.dispose();}
@override Widget build(BuildContext c,WidgetRef r)=>Scaffold(appBar:AppBar(title:const Text('Операции')),floatingActionButton:FloatingActionButton(onPressed:()=>add(c,r),child:const Icon(Icons.add)),body:r.watch(transactionsProvider).when(data:(items)=>items.isEmpty?const Center(child:Text('Операций пока нет')):ListView(children:items.map((x)=>ListTile(title:Text(x.description.isEmpty?x.category:x.description),subtitle:Text(x.kind),trailing:Text(money(x.amount,x.currency)))).toList()),loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('$e'))));}
